// 0. 导入所需模块

import fs from 'fs/promises';
// 1. 在控制台输出内容
console.log('你好，这是你的自定义编辑器！');
// 2. 定义一个简单函数
function add(a, b) {
  return a + b;
}
// 3. 调用函数并显示结果
const result = add(2, 3);
console.log(`2 与 3 的和是：${result}`);
// 4. 使用 top-level await 获取数据
const response = await fetch('https://pokeapi.co/api/v2/pokemon/1');
const data = await response.json();
// 5. 显示获取的部分数据
console.log(`一号宝可梦是：${data.name}`);
// 6. 创建数组并映射
const numbers = [1, 2, 3, 4, 5];
const squared = numbers.map(num => num * num);
console.log('平方值：', squared);
// 7. 创建文件以便稍后读取
await fs.writeFile('example.txt', '1 2 3 4 5');
const fileContent = (await fs.readFile('example.txt')).toString();
console.log('文件内容：', fileContent.split(' ').map(e => Number(e)));
